// Bundles every shop migration (apps/api/drizzle/NNNN_*.sql) into a single
// generated module the Worker can import at signup time:
//   pnpm --filter goldos-api bundle:migrations
// Rerun whenever drizzle/* changes; the generated file is committed so
// deploys and tests work without a build step.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const dir = join(here, "..", "drizzle");
const out = join(here, "..", "src", "db", "shop-migrations.ts");

const files = readdirSync(dir)
  .filter((x) => /^\d{4}_.*\.sql$/.test(x))
  .sort();
if (files.length === 0) throw new Error(`no migrations found in ${dir}`);

const entries = files.map((name) => `  { name: ${JSON.stringify(name)}, sql: ${JSON.stringify(readFileSync(join(dir, name), "utf8"))} },`);
writeFileSync(
  out,
  `// GENERATED by scripts/bundle-migrations.mjs — do not edit.\n// Rerun \`pnpm --filter goldos-api bundle:migrations\` when drizzle/* changes.\nexport const SHOP_MIGRATIONS: Array<{ name: string; sql: string }> = [\n${entries.join("\n")}\n];\n`
);
console.log(`bundled ${files.length} migrations → src/db/shop-migrations.ts`);
